#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

enum State { EMPTY, OK, FULL };

State get_state(int64 a, int64 b, int64 c) {
    if (a == 0 && b == 0)
        return c == 0 ? FULL : EMPTY;
    return OK;
}

i128 det2(int64 a, int64 b, int64 c, int64 d) {
    return (i128)a * d - (i128)b * c;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 a1, b1, c1, a2, b2, c2;
    cin >> a1 >> b1 >> c1;
    cin >> a2 >> b2 >> c2;

    State s1 = get_state(a1, b1, c1);
    State s2 = get_state(a2, b2, c2);

    if (s1 == EMPTY || s2 == EMPTY) {
        cout << "0\n";
    } else if (s1 == FULL || s2 == FULL) {
        cout << "-1\n";
    } else if (det2(a1, b1, a2, b2) != 0) {
        cout << "1\n";
    } else if (det2(a1, c1, a2, c2) == 0 &&
               det2(b1, c1, b2, c2) == 0) {
        cout << "-1\n";
    } else {
        cout << "0\n";
    }

    return 0;
}

